using System;
using System.Linq;
using Revora;
using Revora.Client;
using Revora.Database;
using Revora.Game;
using Revora.Network.GamePackets;
internal static partial class CheckCandidateArenaLifecycle {
    static string FreshGuildHuntSnapshot(GameState p){return Convert.ToString(Sql(@"SELECT json_build_object('prior',@prior::json,'beast',(SELECT row_to_json(b) FROM revora_guild_beast_days b WHERE day='2041-03-10'))::text","prior",FreshGuildWarSnapshot(p)));}
    static void FreshGuildHuntProcess(string phase){
        DateTime now=new DateTime(2041,3,10,20,0,0,DateTimeKind.Local).ToUniversalTime();Feature("GuildSeasonWar").GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));Feature("GuildWarPurses").GetField("nextPoll",Hidden).SetValue(null,DateTime.MaxValue);Feature("GuildBeastEvent").GetField("Clock",Hidden).SetValue(null,(Func<DateTime>)(()=>now));
        var p=FreshLoadSaved(true,true);EntityVariableTable.Load(p);SubClassTable.Load(p.Entity);ChiTable.Load(p);p.Quests.Load();Revora.Database.KnownPersons.LoadMentor(p);WayofHeroes.Load(p);Server.GamePool=new[]{p};Require(!p.Fake && p.Account.State==AccountTable.AccountState.Player && !PirateFenced(p) && p.Guild!=null && p.Guild.Name=="FreshBanner");
        if((bool)Sql("SELECT to_regclass('revora_fresh_guild_hunt_probe') IS NULL")){
            Require(phase.EndsWith("purse") && FreshGuildWarSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_guild_war_probe")) && (long)Sql("SELECT count(*) FROM revora_guild_beast_days WHERE day='2041-03-10'")==0);Sql("CREATE TABLE revora_fresh_guild_hunt_probe(stage text,hits integer,snapshot text);INSERT INTO revora_fresh_guild_hunt_probe VALUES('new',0,@snapshot)","snapshot",FreshGuildHuntSnapshot(p));
        }
        Require(FreshGuildHuntSnapshot(p)==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_guild_hunt_probe")));string stage=Convert.ToString(Sql("SELECT stage FROM revora_fresh_guild_hunt_probe"));
        if(phase.EndsWith("purse")){
            Require(stage=="new");FreshClassicTalk(p,1020,10028,0);var key=Revora.Game.ConquerStructures.Warehouse.WarehouseID.ApeCity;if(!p.Warehouses.ContainsKey(key))p.Warehouses.Add(key,new Revora.Game.ConquerStructures.Warehouse(p,key));var bank=p.Warehouses[key];int store=Math.Max(0,p.Inventory.Count-32);Require(bank.Count+store<=60);
            foreach(var item in p.Inventory.Objects.Where(i=>i.Days==0).Take(store).ToArray()){var frame=new byte[172];Revora.Network.Writer.WriteUInt16(164,0,frame);Revora.Network.Writer.WriteUInt16(1102,2,frame);Revora.Network.Writer.WriteUInt32(10028,4,frame);frame[12]=1;frame[13]=10;Revora.Network.Writer.WriteUInt32(item.UID,18,frame);Revora.Network.Writer.WriteUInt64(Revora.Network.PacketHandler.ClientSeal,164,frame);Warehouse.Process(frame,p);Require(!p.Inventory.ContainsUID(item.UID) && bank.ContainsUID(item.UID));}Require(p.Inventory.Count==32);
            uint cp=p.Entity.ConquerPoints,rp=p.Entity.RevoraPoint;ulong gold=p.Entity.Money;var before=p.Inventory.Objects.Select(i=>i.UID).ToArray();FreshClassicTalk(p,1002,10003,88);HeartTalk(p,10003,88);var added=p.Inventory.Objects.Where(i=>!before.Contains(i.UID)).ToArray();Require(added.Length==6 && added.Count(i=>i.Bound && ConquerItemInformation.BaseInformations[i.ID].PurificationLevel==7)==1 && before.All(uid=>p.Inventory.ContainsUID(uid)));
            Require((bool)Sql("SELECT claimed_at IS NOT NULL AND @cp+cp=@nextcp AND @rp+rvp=@nextrp AND @gold+gold=@nextgold FROM revora_guild_purses WHERE day='2041-03-10' AND uid=@uid","cp",(long)cp,"rp",(long)rp,"gold",(long)gold,"nextcp",(long)p.Entity.ConquerPoints,"nextrp",(long)p.Entity.RevoraPoint,"nextgold",(long)p.Entity.Money,"uid",(long)p.Entity.UID));stage="purse";System.Console.WriteLine("[fresh-guild-hunt] purse cp="+(p.Entity.ConquerPoints-cp)+" rvp="+(p.Entity.RevoraPoint-rp)+" silver="+(p.Entity.Money-gold));
        }else if(phase.EndsWith("hunt")){
            Require(stage=="purse");ulong gold=p.Entity.Money,fund=p.Guild.SilverFund;lock(p.ItemSyncRoot)Require((bool)Call(Feature("GuildDonations"),"Donate",p,500000u,false));Require(p.Entity.Money==gold-500000 && p.Guild.SilverFund==fund+500000);FreshClassicTalk(p,1002,10003,89);Require(p.Entity.MapID==1038);HeartTalk(p,8150,1);HeartTalk(p,8150,1);Require(p.Guild.SilverFund==fund);now=now.AddHours(1);Call(Feature("GuildBeastEvent"),"Tick");var beast=p.Map.Entities.Values.Single(e=>e.MonsterInfo!=null && e.MonsterInfo.ID==7006 && !e.Dead);p.Entity.X=beast.X;p.Entity.Y=(ushort)(beast.Y+1);p.Screen.Add(beast);p.Attackable=true;p.CantAttack=Time32.Now.AddSeconds(-1);int hits=0;
            while(!beast.Dead && hits<10000){p.Entity.AttackStamp=Time32.Now.AddSeconds(-2);Attack.HandleAttack(new Attack(true){Attacker=p.Entity.UID,Attacked=beast.UID,X=beast.X,Y=beast.Y,AttackType=Attack.Melee},p);hits++;}Require(beast.Dead && !p.Entity.Dead && !PirateFenced(p) && (long)Sql("SELECT count(*) FROM revora_guild_beast_days WHERE day='2041-03-10' AND state='killed' AND killer=@uid AND claimed_at IS NULL","uid",(long)p.Entity.UID)==1);Sql("UPDATE revora_fresh_guild_hunt_probe SET hits=@hits","hits",hits);stage="killed";System.Console.WriteLine("[fresh-guild-hunt] beast melee hits="+hits);
        }else{
            bool prize=phase.EndsWith("prize");Require(stage==(prize?"killed":"paid") && (prize || phase.EndsWith("reload")));now=now.AddHours(3);var before=p.Inventory.Objects.Select(i=>i.UID).ToArray();HeartTalk(p,8150,2);HeartTalk(p,8150,2);var added=p.Inventory.Objects.Where(i=>!before.Contains(i.UID)).ToArray();Require(before.All(uid=>p.Inventory.ContainsUID(uid)));
            if(prize)Require(added.Length==2 && added.Any(i=>i.ID==1088000 && !i.Bound) && added.Any(i=>i.Bound && ConquerItemInformation.BaseInformations[i.ID].PurificationLevel==7));else Require(added.Length==0);
            Require((long)Sql("SELECT count(*) FROM revora_guild_beast_days WHERE day='2041-03-10' AND claimed_uid=@uid AND claimed_at IS NOT NULL AND soul_uid>0","uid",(long)p.Entity.UID)==1);stage="paid";
        }
        new TitleStorage().Login(p);Require(EntityTable.SaveEntity(p));string exact=FreshGuildHuntSnapshot(p);if(!phase.EndsWith("reload"))Sql("UPDATE revora_fresh_guild_hunt_probe SET stage=@stage,snapshot=@snapshot","stage",stage,"snapshot",exact);else Require(exact==Convert.ToString(Sql("SELECT snapshot FROM revora_fresh_guild_hunt_probe")));Require(!PirateFenced(p));System.Console.WriteLine("[career-process] "+phase+"-passed bag="+p.Inventory.Count+" cp="+p.Entity.ConquerPoints+" rvp="+p.Entity.RevoraPoint);Server.CommandsAI("@close");throw new InvalidOperationException("Fresh guild hunt did not close.");
    }
}
